SELECT org_id, org_name, org_code, parent_id, parent_name, org_level, org_type, leader, contact, phone, email, address, status, description, create_by, create_time, update_by, update_time FROM finance_org
AND org_name LIKE '%' || #{params.orgName} || '%'
AND org_code = #{params.orgCode}
AND parent_id = #{params.parentId}
AND org_type = #{params.orgType}
AND status = #{params.status}
ORDER BY org_level, create_time

SELECT org_id, org_name, org_code, parent_id, parent_name, org_level, org_type, status FROM finance_org
AND status = #{params.status}
ORDER BY org_level, org_code

SELECT ORG_ID as orgId, ORG_CODE as orgCode, ORG_NAME as orgName, PARENT_ORG_ID as parentOrgId, ORG_LEVEL as orgLevel, ORG_TYPE as orgType, IS_ENABLED as isEnabled, REMARK as remark, BOOK_ID as bookId, TENANT_ID as tenantId, CREATE_TIME as createTime, UPDATE_TIME as updateTime FROM TBL_FINANCE_ORG
AND TENANT_ID = #{params.tenantId}
AND BOOK_ID = #{params.bookId}
AND ORG_NAME LIKE '%' || #{params.orgName} || '%'
AND ORG_CODE = #{params.orgCode}
AND PARENT_ORG_ID = #{params.parentOrgId}
AND ORG_TYPE = #{params.orgType}
AND IS_ENABLED = #{params.isEnabled}
AND IS_DELETED = 0
ORDER BY ORG_LEVEL, ORG_CODE

SELECT COUNT(1)
FROM TBL_FINANCE_ORG


        AND TENANT_ID = #{params.tenantId}


        AND BOOK_ID = #{params.bookId}


        AND ORG_NAME LIKE '%' || #{params.orgName} || '%'


        AND ORG_CODE = #{params.orgCode}


        AND PARENT_ORG_ID = #{params.parentOrgId}


        AND ORG_TYPE = #{params.orgType}


        AND IS_ENABLED = #{params.isEnabled}

    AND IS_DELETED = 0

SELECT ORG_ID as orgId, ORG_CODE as orgCode, ORG_NAME as orgName, PARENT_ORG_ID as parentOrgId, ORG_LEVEL as orgLevel, ORG_PATH as orgPath, ORG_TYPE as orgType, IS_ENABLED as isEnabled, REMARK as remark, BOOK_ID as bookId, TENANT_ID as tenantId, CREATE_TIME as createTime, UPDATE_TIME as updateTime FROM TBL_FINANCE_ORG
AND TENANT_ID = #{params.tenantId}
AND BOOK_ID = #{params.bookId}
AND IS_ENABLED = #{params.isEnabled}
AND IS_DELETED = 0
ORDER BY ORG_LEVEL, ORG_CODE

SELECT COUNT(1)
FROM TBL_FINANCE_ORG


        AND TENANT_ID = #{params.tenantId}


        AND BOOK_ID = #{params.bookId}


        AND IS_ENABLED = #{params.isEnabled}

    AND IS_DELETED = 0
